WITH months AS (SELECT DISTINCT CAST(date_trunc('month', date_day) AS DATE) AS month_start FROM {{ ref('time_spine') }}), month_bounds AS (SELECT month_start, CAST(month_start + INTERVAL '1 month' - INTERVAL '1 day' AS DATE) AS month_end FROM months), valid_cards AS (SELECT card_id, member_id, card_type, valid_from, valid_until, ended_at FROM {{ ref('cards') }} WHERE card_type IN ('悦享年卡', '家庭季卡') AND valid_from IS NOT NULL AND valid_until IS NOT NULL AND valid_from < valid_until AND (ended_at IS NULL OR (ended_at > valid_from AND ended_at < valid_until))), eligible_account_months AS (SELECT DISTINCT b.month_start, c.member_id FROM month_bounds b JOIN valid_cards c ON c.valid_from <= b.month_end AND b.month_end < c.valid_until AND (c.ended_at IS NULL OR b.month_end < c.ended_at)), month_orders AS (SELECT member_id, CAST(date_trunc('month', ordered_at) AS DATE) AS month_start, COUNT(*) AS order_count, SUM(paid_cents - refund_cents) AS net_sales_cents FROM {{ ref('orders_enriched') }} WHERE status = 'paid' AND paid_cents - refund_cents > 0 GROUP BY member_id, CAST(date_trunc('month', ordered_at) AS DATE)), account_month AS (SELECT e.month_start, e.member_id, COALESCE(o.order_count, 0) AS order_count, COALESCE(o.net_sales_cents, 0) AS net_sales_cents FROM eligible_account_months e LEFT JOIN month_orders o ON e.member_id = o.member_id AND e.month_start = o.month_start), month_agg AS (SELECT month_start, COUNT(DISTINCT CASE WHEN order_count >= 1 THEN member_id END) AS paid_buyer_count, SUM(order_count) AS paid_order_count, COUNT(DISTINCT CASE WHEN order_count >= 2 THEN member_id END) AS paid_repeat_buyer_count, SUM(net_sales_cents) AS paid_sales_cents FROM account_month GROUP BY month_start) SELECT m.month_start, CAST(m.month_start AS VARCHAR) AS month_key, COALESCE(a.paid_buyer_count, 0) AS paid_buyer_count, COALESCE(a.paid_order_count, 0) AS paid_order_count, COALESCE(a.paid_repeat_buyer_count, 0) AS paid_repeat_buyer_count, COALESCE(a.paid_sales_cents, 0) AS paid_sales_cents FROM months m LEFT JOIN month_agg a ON m.month_start = a.month_start